-- ci-controle-personne-refuse-de-decliner — Il demande d'abord sur quel fondement vous le contrôlez
SELECT public.fn_cp_import_case('ci-controle-personne-refuse-de-decliner', '{"slug": "ci-controle-personne-refuse-de-decliner", "title": "Il demande d''abord sur quel fondement vous le contrôlez", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures. Vous procédez à un contrôle d''identité sur la voie publique, dans le cadre d''une réquisition du procureur de la République en vigueur sur ce secteur. La personne contrôlée, un homme d''une trentaine d''années, ne refuse pas de coopérer mais demande calmement, avant de sortir ses papiers, sur quel fondement précis vous le contrôlez. Il n''est ni agressif ni provocateur : sa question semble sincère et il attend une réponse avant de continuer. Deux passants ralentissent le pas en observant l''échange, sans intervenir. Vous disposez de la réquisition sur vous, mais devez formuler une réponse claire et compréhensible sans documentation juridique complexe.", "questions": [{"position": 1, "max_points": 5, "label": "Comment répondez-vous à cette demande de fondement légal du contrôle ?", "hint": "Une question légitime mérite une réponse claire, pas une réaction défensive.", "perfect": "Je réponds sans me braquer, cette question restant légitime et ne constituant en rien une remise en cause de mon autorité. J''explique simplement que ce contrôle s''inscrit dans le cadre d''une réquisition du procureur en vigueur sur ce secteur, sans entrer dans un jargon juridique inutile. Je reste factuelle et posée, cette clarté contribuant à apaiser une situation qui n''a pourtant rien d''anormal. Je propose, si la personne le souhaite, de lui montrer la réquisition ou de lui indiquer comment en vérifier l''existence.", "points": [{"position": 1, "label": "Répondre sans se braquer face à une question légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["reponse sans se braquer", "question legitime", "calme maintenu"]}]}, {"position": 2, "label": "Expliquer simplement le cadre de la réquisition sans jargon inutile", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarté de l''explication.", "groups": [{"position": 1, "keywords": ["requisition expliquee", "jargon evite", "explication simple"]}]}, {"position": 3, "label": "Rester factuelle et posée dans la réponse", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Posture professionnelle.", "groups": [{"position": 1, "keywords": ["factuelle et posee", "ton maitrise", "professionnalisme"]}]}, {"position": 4, "label": "Proposer de montrer la réquisition ou d''indiquer comment la vérifier", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence supplémentaire.", "groups": [{"position": 1, "keywords": ["requisition montree", "verification proposee", "transparence assuree"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment poursuivez-vous le contrôle une fois cette explication donnée ?", "hint": "Le fait d''avoir répondu ne dispense pas de mener le contrôle jusqu''au bout normalement.", "perfect": "Je poursuis le contrôle normalement une fois cette explication donnée, cette clarification ne suspendant en rien la procédure habituelle. Je demande les documents d''identité avec la même courtoisie qu''en début d''échange. Je reste attentive au comportement de la personne pendant cette vérification, sans pour autant adopter une suspicion excessive après cette question initiale. Je conclus le contrôle rapidement dès lors que les documents présentés sont en règle.", "points": [{"position": 1, "label": "Poursuivre le contrôle normalement après l''explication", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Continuité de la procédure.", "groups": [{"position": 1, "keywords": ["controle poursuivi", "procedure normale", "continuite assuree"]}]}, {"position": 2, "label": "Demander les documents avec la même courtoisie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie maintenue.", "groups": [{"position": 1, "keywords": ["documents demandes", "courtoisie maintenue", "ton constant"]}]}, {"position": 3, "label": "Rester attentive sans suspicion excessive après la question initiale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Équilibre entre vigilance et présomption.", "groups": [{"position": 1, "keywords": ["vigilance mesuree", "suspicion evitee", "equilibre maintenu"]}]}, {"position": 4, "label": "Conclure rapidement le contrôle si les documents sont en règle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Efficacité de la clôture.", "groups": [{"position": 1, "keywords": ["controle conclu", "documents en regle", "rapidite assuree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la présence des passants qui observent cet échange ?", "hint": "Un contrôle mené calmement devant témoins reste la meilleure réponse à l''observation publique.", "perfect": "Je ne modifie pas ma conduite du contrôle en raison de la présence de ces passants, ce comportement restant identique qu''il y ait ou non des témoins. Je reste consciente que cette observation publique renforce l''importance de rester exemplaire dans le ton et l''attitude. Je n''interpelle pas ces passants s''ils n''interviennent pas directement dans l''échange, leur seule présence ne constituant pas un trouble. Je reste concentrée sur la personne contrôlée sans me laisser distraire par ce public.", "points": [{"position": 1, "label": "Ne pas modifier sa conduite en raison de la présence de témoins", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Constance du comportement.", "groups": [{"position": 1, "keywords": ["conduite inchangee", "temoins presents", "constance assuree"]}]}, {"position": 2, "label": "Rester exemplaire dans le ton compte tenu de l''observation publique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Exemplarité renforcée.", "groups": [{"position": 1, "keywords": ["ton exemplaire", "observation publique", "exemplarite renforcee"]}]}, {"position": 3, "label": "Ne pas interpeller les passants s''ils n''interviennent pas", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Absence d''escalade inutile.", "groups": [{"position": 1, "keywords": ["passants non interpelles", "absence d intervention", "escalade evitee"]}]}, {"position": 4, "label": "Rester concentrée sur la personne contrôlée sans distraction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Concentration maintenue.", "groups": [{"position": 1, "keywords": ["concentration maintenue", "distraction evitee", "attention centree"]}]}]}]}'::jsonb);

-- ci-personne-sans-document-identite-verifiable — Il donne un nom mais aucun élément ne permet de le vérifier
SELECT public.fn_cp_import_case('ci-personne-sans-document-identite-verifiable', '{"slug": "ci-personne-sans-document-identite-verifiable", "title": "Il donne un nom mais aucun élément ne permet de le vérifier", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Lors d''un contrôle d''identité, un homme déclare son nom oralement mais ne présente aucun document permettant de le vérifier : il affirme avoir oublié ses papiers chez lui. Il ne dispose ni de carte d''identité, ni de permis, ni d''aucun autre document, et aucun élément à portée immédiate ne permet de confirmer son identité déclarée. Il reste coopératif dans le ton mais insiste pour repartir rapidement, expliquant être attendu. Vous devez déterminer les moyens de vérification disponibles avant d''envisager toute suite à ce contrôle, sans céder à la pression du temps qu''il exprime.", "questions": [{"position": 1, "max_points": 5, "label": "Quels moyens mettez-vous en œuvre pour tenter de vérifier cette identité déclarée ?", "hint": "Plusieurs moyens existent avant d''envisager une mesure plus contraignante.", "perfect": "J''épuise les moyens de vérification disponibles avant d''envisager toute suite, cette démarche restant prioritaire face à l''absence de document. Je lui demande s''il dispose d''un moyen indirect de confirmer son identité, comme une photo de document sur son téléphone ou un contact pouvant la confirmer. Je vérifie, si possible, son identité déclarée dans les fichiers accessibles depuis mon terminal. Je reste méthodique dans cette recherche, sans conclure trop vite à une impossibilité de vérification.", "points": [{"position": 1, "label": "Épuiser les moyens de vérification avant toute suite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["moyens epuises", "verification prioritaire", "suite differee"]}]}, {"position": 2, "label": "Demander un moyen indirect de confirmation (photo, contact)", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Alternatives explorées.", "groups": [{"position": 1, "keywords": ["moyen indirect", "photo document", "contact confirmant"]}]}, {"position": 3, "label": "Vérifier l''identité déclarée dans les fichiers accessibles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérification fichiers.", "groups": [{"position": 1, "keywords": ["fichiers consultes", "identite verifiee", "terminal utilise"]}]}, {"position": 4, "label": "Rester méthodique sans conclure trop vite à une impossibilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur de la démarche.", "groups": [{"position": 1, "keywords": ["methode rigoureuse", "conclusion differee", "impossibilite evitee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment répondez-vous à son insistance pour repartir rapidement ?", "hint": "La pression temporelle qu''il exprime ne doit pas accélérer une vérification incomplète.", "perfect": "Je reste ferme sur la nécessité de finaliser cette vérification avant qu''il ne reparte, cette exigence restant proportionnée à l''impossibilité actuelle de confirmer son identité. J''explique clairement pourquoi cette vérification prend du temps, sans dramatiser la situation. Je reste courtoise malgré son insistance, cette pression ne devant pas altérer ma rigueur. Je l''informe de la durée probable de cette vérification pour qu''il puisse s''organiser en conséquence.", "points": [{"position": 1, "label": "Rester ferme sur la nécessité de finaliser la vérification", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Fermeté proportionnée.", "groups": [{"position": 1, "keywords": ["fermete maintenue", "verification finalisee", "necessite affirmee"]}]}, {"position": 2, "label": "Expliquer clairement pourquoi cette vérification prend du temps", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explication du délai.", "groups": [{"position": 1, "keywords": ["delai explique", "temps justifie", "clarte assuree"]}]}, {"position": 3, "label": "Rester courtoise malgré son insistance", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie maintenue sous pression.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "insistance geree", "pression resistee"]}]}, {"position": 4, "label": "Informer de la durée probable pour qu''il s''organise", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information pratique donnée.", "groups": [{"position": 1, "keywords": ["duree indiquee", "organisation facilitee", "information donnee"]}]}]}, {"position": 3, "max_points": 5, "label": "Si aucun moyen ne permet de vérifier son identité, quelle suite envisagez-vous ?", "hint": "Le code de procédure pénale prévoit un cadre spécifique en cas d''impossibilité de justifier son identité.", "perfect": "J''envisage, en dernier recours et seulement après épuisement de tous les moyens disponibles, la procédure prévue en cas d''impossibilité de justifier son identité, cette mesure restant proportionnée à cette situation précise. J''explique posément à la personne pourquoi cette suite devient nécessaire, sans dramatiser ni minimiser. Je reste mesurée dans la mise en œuvre de cette mesure, celle-ci ne constituant pas une sanction mais une nécessité procédurale. Je documente précisément l''ensemble des démarches de vérification déjà entreprises.", "points": [{"position": 1, "label": "Envisager la procédure d''impossibilité de justifier son identité en dernier recours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Proportionnalité de la mesure.", "groups": [{"position": 1, "keywords": ["dernier recours", "impossibilite constatee", "procedure adaptee"]}]}, {"position": 2, "label": "Expliquer posément pourquoi cette suite devient nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Explication de la mesure.", "groups": [{"position": 1, "keywords": ["suite expliquee", "necessite justifiee", "ton posee"]}]}, {"position": 3, "label": "Rester mesurée, cette mesure n''étant pas une sanction", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Nature non punitive rappelée.", "groups": [{"position": 1, "keywords": ["mesure non punitive", "necessite proceduriale", "mesure appliquee"]}]}, {"position": 4, "label": "Documenter précisément les démarches de vérification entreprises", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité de la procédure.", "groups": [{"position": 1, "keywords": ["demarches documentees", "traçabilite assuree", "verifications tracees"]}]}]}]}'::jsonb);

