SELECT public.fn_cp_import_case('ci-controle-groupe-personnes', '{"slug": "ci-controle-groupe-personnes", "title": "Ils sont huit, deux commencent à filmer", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 21 heures. Vous devez procéder à un contrôle d''identité concernant un groupe de huit personnes rassemblées sur une place, dans le cadre d''une réquisition en vigueur sur ce secteur connu pour des trafics. Dès votre approche, deux membres du groupe sortent leur téléphone et commencent à filmer l''intervention, sans agressivité mais de façon ostensible. L''effectif du groupe est nettement supérieur au vôtre, votre collègue et vous n''étant que deux sur place, un renfort n''étant pas immédiatement disponible. Certains membres du groupe se rapprochent les uns des autres, sans geste hostile, mais rendant plus difficile une approche individualisée de chacun. Vous devez décider comment organiser ce contrôle sans céder à la précipitation ni laisser la situation vous échapper.", "questions": [{"position": 1, "max_points": 5, "label": "Comment adaptez-vous votre dispositif face à ce nombre et à cette configuration ?", "hint": "Un contrôle à deux face à huit personnes exige une méthode différente d''un contrôle individuel.", "perfect": "J''adapte mon dispositif au nombre en sollicitant un renfort avant d''engager un contrôle individualisé de chacun, cet effectif déséquilibré rendant prudente cette précaution. Je choisis, en l''attente du renfort, de maintenir une communication claire avec le groupe sur l''objet de mon intervention plutôt que de commencer isolément. Je reste méthodique dans le positionnement de mon collègue et moi-même, en gardant une vision d''ensemble du groupe. Je ne cherche pas à précipiter un contrôle individuel avant d''avoir les moyens suffisants pour le mener sereinement.", "points": [{"position": 1, "label": "Solliciter un renfort avant d''engager un contrôle individualisé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["renfort sollicite", "effectif adapte", "controle individualise differe"]}]}, {"position": 2, "label": "Communiquer clairement sur l''objet de l''intervention en attendant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence pendant l''attente.", "groups": [{"position": 1, "keywords": ["communication claire", "objet explique", "attente geree"]}]}, {"position": 3, "label": "Maintenir une vision d''ensemble du groupe avec son collègue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Positionnement méthodique.", "groups": [{"position": 1, "keywords": ["vision d ensemble", "positionnement methodique", "groupe surveille"]}]}, {"position": 4, "label": "Ne pas précipiter le contrôle individuel avant d''avoir les moyens suffisants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Absence de précipitation.", "groups": [{"position": 1, "keywords": ["precipitation evitee", "moyens suffisants", "patience assuree"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment réagissez-vous face aux deux personnes qui filment l''intervention ?", "hint": "Filmer une intervention policière sur la voie publique n''est pas, en soi, un acte répréhensible.", "perfect": "Je n''interdis pas de filmer, cet acte n''étant en soi pas répréhensible sur la voie publique dès lors qu''il ne gêne pas matériellement l''intervention. Je reste vigilante à ce que cette captation ne se transforme pas en obstruction physique de mon action ou de celle de mon collègue. J''explique, si nécessaire, que je n''ai pas d''objection à cette captation tant qu''elle reste à distance raisonnable. Je ne me laisse pas déstabiliser par cette exposition, mon comportement devant rester identique qu''il y ait captation ou non.", "points": [{"position": 1, "label": "Ne pas interdire de filmer sur la voie publique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Respect du droit de filmer.", "groups": [{"position": 1, "keywords": ["filmer autorise", "voie publique", "captation non interdite"]}]}, {"position": 2, "label": "Rester vigilante à ce que la captation ne devienne pas une obstruction physique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distinction filmer/obstruction.", "groups": [{"position": 1, "keywords": ["obstruction evitee", "distance raisonnable", "vigilance maintenue"]}]}, {"position": 3, "label": "Expliquer l''absence d''objection tant que la distance est respectée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Clarté de la position.", "groups": [{"position": 1, "keywords": ["explication donnee", "distance respectee", "position clarifiee"]}]}, {"position": 4, "label": "Ne pas se laisser déstabiliser par cette exposition", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Constance du comportement.", "groups": [{"position": 1, "keywords": ["destabilisation evitee", "comportement constant", "exposition geree"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois le renfort arrivé, comment menez-vous concrètement ce contrôle collectif ?", "hint": "Un contrôle mené individuellement, personne par personne, reste préférable à une approche globale et confuse.", "perfect": "Je mène ce contrôle personne par personne avec les effectifs désormais disponibles, cette approche individualisée restant plus rigoureuse qu''un traitement global et confus du groupe. Je répartis les rôles avec mes collègues pour garder une vue d''ensemble pendant que chacun est contrôlé individuellement. Je reste courtoise avec chaque personne contrôlée, sans reporter sur elle une tension liée au nombre. Je conclus ce contrôle collectif de la même manière qu''un contrôle individuel, sans traitement différencié injustifié.", "points": [{"position": 1, "label": "Mener le contrôle personne par personne avec les effectifs disponibles", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Méthode individualisée.", "groups": [{"position": 1, "keywords": ["controle individualise", "personne par personne", "methode rigoureuse"]}]}, {"position": 2, "label": "Répartir les rôles avec les collègues pour garder une vue d''ensemble", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coordination de l''équipe.", "groups": [{"position": 1, "keywords": ["roles repartis", "vue d ensemble", "coordination assuree"]}]}, {"position": 3, "label": "Rester courtoise avec chaque personne sans reporter la tension du nombre", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie individuelle maintenue.", "groups": [{"position": 1, "keywords": ["courtoisie individuelle", "tension non reportee", "traitement equitable"]}]}, {"position": 4, "label": "Conclure sans traitement différencié injustifié", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Égalité de traitement.", "groups": [{"position": 1, "keywords": ["traitement egal", "conclusion equitable", "differenciation evitee"]}]}]}]}'::jsonb);

-- ci-controle-personne-en-situation-irreguliere — Elle voyage avec deux enfants en bas âge
SELECT public.fn_cp_import_case('ci-controle-personne-en-situation-irreguliere', '{"slug": "ci-controle-personne-en-situation-irreguliere", "title": "Elle voyage avec deux enfants en bas âge", "theme_slug": "controle-identite", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 10 heures. Dans une gare routière, vous contrôlez l''identité d''une femme voyageant avec deux enfants en bas âge, l''un dans une poussette et l''autre tenu par la main. Les documents qu''elle présente laissent apparaître une situation administrative irrégulière au regard du droit au séjour. Elle reste calme mais visiblement inquiète, et l''aîné des enfants, sentant la tension, commence à s''agripper à elle. Aucun tiers ne peut immédiatement prendre en charge ces enfants si une suite était donnée à ce contrôle. Vous devez déterminer la conduite à tenir en conciliant l''exigence administrative de la situation constatée et la présence de ces deux enfants qui n''ont, eux, commis aucun manquement et dépendent entièrement de leur mère pour tout ce qui les concerne.", "questions": [{"position": 1, "max_points": 5, "label": "Comment menez-vous ce contrôle en tenant compte de la présence des enfants ?", "hint": "La présence d''enfants en bas âge ne suspend pas le contrôle mais en modifie la manière.", "perfect": "Je mène ce contrôle avec une attention particulière à la présence de ces deux enfants, cette vigilance restant nécessaire sans pour autant suspendre le contrôle lui-même. J''adopte un ton mesuré et rassurant, cette approche limitant l''anxiété visible chez l''aîné qui perçoit la tension. Je prends le temps nécessaire pour cette vérification, sans précipitation qui pourrait accentuer l''inquiétude de cette femme et de ses enfants. Je reste attentive aux besoins immédiats des enfants pendant toute la durée de ce contrôle, notamment leur confort et leur sécurité.", "points": [{"position": 1, "label": "Mener le contrôle avec attention à la présence des enfants sans le suspendre", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["attention aux enfants", "controle maintenu", "vigilance assuree"]}]}, {"position": 2, "label": "Adopter un ton mesuré et rassurant limitant l''anxiété de l''aîné", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion de l''anxiété de l''enfant.", "groups": [{"position": 1, "keywords": ["ton rassurant", "anxiete limitee", "aine apaise"]}]}, {"position": 3, "label": "Prendre le temps nécessaire sans précipitation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Temps adapté à la situation.", "groups": [{"position": 1, "keywords": ["temps necessaire", "precipitation evitee", "inquietude limitee"]}]}, {"position": 4, "label": "Rester attentive au confort et à la sécurité des enfants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Attention pratique aux enfants.", "groups": [{"position": 1, "keywords": ["confort des enfants", "securite assuree", "besoins immediats"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment intégrez-vous la présence des enfants dans votre appréciation des suites à donner ?", "hint": "Toute décision doit prendre en compte l''intérêt supérieur de ces deux enfants, qui n''ont commis aucun manquement.", "perfect": "J''intègre systématiquement la présence de ces enfants dans mon appréciation des suites, leur intérêt supérieur constituant une considération essentielle indépendamment de la situation administrative de leur mère. Je rends compte avec précision de cette présence à ma hiérarchie et aux services compétents, cette information devant peser dans la décision prise. Je m''assure qu''aucune suite ne soit donnée sans que la question de la prise en charge de ces enfants soit résolue au préalable. Je reste factuelle sur la situation administrative constatée, sans y ajouter de jugement personnel sur cette femme.", "points": [{"position": 1, "label": "Intégrer l''intérêt supérieur des enfants dans l''appréciation des suites", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Intérêt supérieur des enfants.", "groups": [{"position": 1, "keywords": ["interet superieur", "enfants integres", "appreciation adaptee"]}]}, {"position": 2, "label": "Rendre compte avec précision de la présence des enfants à la hiérarchie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transmission de l''information.", "groups": [{"position": 1, "keywords": ["compte rendu precis", "hierarchie informee", "presence signalee"]}]}, {"position": 3, "label": "S''assurer que la prise en charge des enfants soit résolue avant toute suite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prise en charge préalable.", "groups": [{"position": 1, "keywords": ["prise en charge resolue", "suite conditionnee", "enfants proteges"]}]}, {"position": 4, "label": "Rester factuelle sans jugement personnel sur la situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Neutralité professionnelle.", "groups": [{"position": 1, "keywords": ["neutralite professionnelle", "factuel sans jugement", "objectivite maintenue"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment communiquez-vous avec cette femme sur le déroulement et les suites de ce contrôle ?", "hint": "L''inquiétude qu''elle exprime mérite une information claire, même si vous ne décidez pas seule des suites.", "perfect": "Je communique avec elle de manière claire sur le déroulement de ce contrôle, cette transparence contribuant à limiter son inquiétude légitime. Je reste honnête sur le fait que cette situation administrative constatée aura des suites, sans pour autant lui promettre une issue que je ne maîtrise pas. J''explique simplement les étapes qui vont suivre, dans la mesure de ce que je peux effectivement lui indiquer à ce stade. Je reste attentive à son état émotionnel tout au long de cet échange, cette femme portant seule la responsabilité de ses deux enfants dans ce moment difficile.", "points": [{"position": 1, "label": "Communiquer clairement sur le déroulement pour limiter l''inquiétude", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence sur le déroulement.", "groups": [{"position": 1, "keywords": ["communication claire", "inquietude limitee", "deroulement explique"]}]}, {"position": 2, "label": "Rester honnête sur les suites sans promettre une issue non maîtrisée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Honnêteté sans fausse promesse.", "groups": [{"position": 1, "keywords": ["honnetete assuree", "issue non promise", "suites annoncees"]}]}, {"position": 3, "label": "Expliquer les étapes suivantes dans la mesure du possible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information pratique donnée.", "groups": [{"position": 1, "keywords": ["etapes expliquees", "information donnee", "mesure du possible"]}]}, {"position": 4, "label": "Rester attentive à son état émotionnel tout au long de l''échange", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Attention émotionnelle continue.", "groups": [{"position": 1, "keywords": ["etat emotionnel", "attention continue", "echange humain"]}]}]}]}'::jsonb);

-- ci-controle-conteste-par-un-temoin — Un passant s'interpose et exige des explications
SELECT public.fn_cp_import_case('ci-controle-conteste-par-un-temoin', '{"slug": "ci-controle-conteste-par-un-temoin", "title": "Un passant s''interpose et exige des explications", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 17 heures. Pendant que vous procédez à un contrôle d''identité sur un trottoir, un passant qui n''a aucun lien avec la personne contrôlée s''arrête, s''interpose physiquement à quelques pas et exige des explications sur les raisons de ce contrôle. Il n''est pas agressif mais se montre insistant, invoquant un principe général selon lequel « on ne peut pas contrôler les gens comme ça sans raison ». La personne contrôlée elle-même reste silencieuse et semble presque gênée par cette intervention extérieure. Ce passant élève progressivement la voix, sans toutefois proférer d''insulte ni de menace, et commence à attirer l''attention d''autres personnes autour de vous.", "questions": [{"position": 1, "max_points": 5, "label": "Comment réagissez-vous face à l''interposition de ce passant qui n''est pas concerné par le contrôle ?", "hint": "Ce tiers n''a pas de droit à interférer dans un contrôle qui ne le concerne pas, mais la manière de l''écarter compte.", "perfect": "J''écarte ce tiers avec calme, ce dernier n''ayant aucun droit à interférer dans un contrôle qui ne le concerne pas directement. Je lui indique fermement mais sans agressivité que je ne peux pas interrompre ce contrôle pour lui donner des explications à ce stade. Je ne me laisse pas entraîner dans une joute verbale avec ce passant, cette énergie devant rester concentrée sur le contrôle en cours. Je reste vigilante à ce que son insistance ne se transforme pas en une entrave concrète à mon action.", "points": [{"position": 1, "label": "Écarter le tiers avec calme sans interrompre le contrôle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["tiers ecarte", "calme maintenu", "controle non interrompu"]}]}, {"position": 2, "label": "Indiquer fermement sans agressivité l''impossibilité de donner des explications immédiates", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Fermeté sans agressivité.", "groups": [{"position": 1, "keywords": ["fermete sans agressivite", "explications differees", "position claire"]}]}, {"position": 3, "label": "Ne pas se laisser entraîner dans une joute verbale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Concentration maintenue.", "groups": [{"position": 1, "keywords": ["joute verbale evitee", "energie concentree", "provocation ignoree"]}]}, {"position": 4, "label": "Rester vigilante à ce que l''insistance ne devienne pas une entrave", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance sur l''escalade possible.", "groups": [{"position": 1, "keywords": ["entrave evitee", "vigilance maintenue", "escalade surveillee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous l''attroupement naissant autour de cet échange ?", "hint": "Un attroupement peut se former rapidement autour d''une contestation, même mineure au départ.", "perfect": "Je reste attentive à cet attroupement naissant sans pour autant y accorder une importance disproportionnée à ce stade précoce. Je maintiens mon attention principale sur le contrôle en cours, tout en gardant une conscience périphérique de l''évolution de ce rassemblement. Je sollicite, si cet attroupement continue de croître, l''appui d''un collègue pour gérer ce tiers pendant que je termine le contrôle initial. Je ne montre aucun signe de nervosité qui pourrait alimenter la curiosité ou la tension de ce public.", "points": [{"position": 1, "label": "Rester attentive sans accorder une importance disproportionnée à ce stade", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Proportionnalité de l''attention.", "groups": [{"position": 1, "keywords": ["attention proportionnee", "attroupement naissant", "vigilance mesuree"]}]}, {"position": 2, "label": "Maintenir l''attention principale sur le contrôle en cours", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Priorité au contrôle initial.", "groups": [{"position": 1, "keywords": ["attention principale", "controle priorise", "concentration maintenue"]}]}, {"position": 3, "label": "Solliciter l''appui d''un collègue si l''attroupement continue de croître", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Appui sollicité en cas d''évolution.", "groups": [{"position": 1, "keywords": ["appui sollicite", "collegue implique", "croissance geree"]}]}, {"position": 4, "label": "Ne montrer aucun signe de nervosité alimentant la curiosité du public", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Maîtrise de soi visible.", "groups": [{"position": 1, "keywords": ["nervosite absente", "maitrise visible", "curiosite non alimentee"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois le contrôle terminé, revenez-vous vers ce passant, et comment ?", "hint": "La question posée par ce passant, même mal amenée, n''était pas totalement infondée dans le principe.", "perfect": "Je reviens brièvement vers ce passant une fois le contrôle terminé, cette démarche restant utile pour apaiser une tension qui s''est construite devant lui. Je lui explique de manière générale, sans détailler les éléments propres à la personne contrôlée, le cadre légal qui permet ce type de contrôle. Je reste courtoise dans cet échange final, cette question n''étant pas totalement infondée dans son principe même si sa manière d''intervenir était inappropriée. Je clos cet échange sans en faire davantage, sans chercher à obtenir des excuses ni à prolonger la discussion.", "points": [{"position": 1, "label": "Revenir brièvement vers le passant pour apaiser la tension", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Apaisement post-contrôle.", "groups": [{"position": 1, "keywords": ["retour vers le passant", "tension apaisee", "demarche utile"]}]}, {"position": 2, "label": "Expliquer le cadre légal général sans détailler les éléments de la personne contrôlée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Confidentialité respectée.", "groups": [{"position": 1, "keywords": ["cadre legal explique", "confidentialite respectee", "details non partages"]}]}, {"position": 3, "label": "Rester courtoise en reconnaissant la légitimité de fond de la question", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie et reconnaissance mesurée.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "question legitime", "fond reconnu"]}]}, {"position": 4, "label": "Clore l''échange sans chercher d''excuses ni le prolonger", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Clôture sobre de l''échange.", "groups": [{"position": 1, "keywords": ["echange clos", "excuses non recherchees", "sobriete assuree"]}]}]}]}'::jsonb);

-- ci-verification-identite-personne-vulnerable — Il ne comprend visiblement pas ce qui lui est demandé
SELECT public.fn_cp_import_case('ci-verification-identite-personne-vulnerable', '{"slug": "ci-verification-identite-personne-vulnerable", "title": "Il ne comprend visiblement pas ce qui lui est demandé", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 14 heures. Lors d''un contrôle d''identité sur la voie publique, l''homme que vous contrôlez présente des signes évidents d''incompréhension face à vos demandes : il répète les mêmes gestes de manière désordonnée, sort et range ses papiers plusieurs fois sans les présenter, et son regard traduit une confusion qui ne semble pas liée à une volonté d''obstruction. Rien dans son comportement ne laisse penser à un état d''ébriété ou de consommation de produit. Il pourrait s''agir d''un trouble cognitif, d''un handicap non déclaré ou d''une simple sidération face à ce contrôle, sans que vous puissiez trancher avec certitude. Vous devez adapter votre approche à cette vulnérabilité apparente tout en menant ce contrôle à son terme.", "questions": [{"position": 1, "max_points": 5, "label": "Comment adaptez-vous votre approche face à cette incompréhension manifeste ?", "hint": "L''origine exacte de cette difficulté importe moins, dans l''immédiat, que l''adaptation de votre méthode.", "perfect": "J''adapte ma démarche à cette vulnérabilité constatée, quelle qu''en soit l''origine exacte que je ne peux déterminer avec certitude à ce stade. Je ralentis mon débit et simplifie mes formulations, ces ajustements facilitant la compréhension sans pour autant infantiliser cette personne. Je répète mes demandes avec patience plutôt que d''y voir une résistance volontaire de sa part. Je reste attentive à tout signe supplémentaire qui pourrait éclairer la nature de cette difficulté, sans pour autant poser un diagnostic qui ne m''appartient pas.", "points": [{"position": 1, "label": "Adapter la démarche à la vulnérabilité constatée quelle qu''en soit l''origine", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["demarche adaptee", "vulnerabilite constatee", "origine incertaine"]}]}, {"position": 2, "label": "Ralentir le débit et simplifier les formulations sans infantiliser", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Communication adaptée et respectueuse.", "groups": [{"position": 1, "keywords": ["debit ralenti", "formulations simplifiees", "respect maintenu"]}]}, {"position": 3, "label": "Répéter avec patience plutôt que d''y voir une résistance volontaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Patience face à l''incompréhension.", "groups": [{"position": 1, "keywords": ["patience appliquee", "resistance non presumee", "repetition calme"]}]}, {"position": 4, "label": "Rester attentive à tout signe éclairant sans poser de diagnostic", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Observation sans diagnostic.", "groups": [{"position": 1, "keywords": ["signes observes", "diagnostic evite", "attention maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Envisagez-vous de solliciter un tiers ou un moyen complémentaire pour faciliter ce contrôle ?", "hint": "Un contrôle qui n''avance pas malgré une approche adaptée peut nécessiter un appui supplémentaire.", "perfect": "J''envisage de solliciter un appui complémentaire si mon adaptation initiale ne suffit pas à faire progresser ce contrôle, cette sollicitation restant proportionnée à la difficulté rencontrée. Je recherche, si possible, un proche ou un tiers connu de cette personne qui pourrait faciliter la communication. Je sollicite si nécessaire mes services pour obtenir un avis ou un appui adapté à ce type de situation. Je ne renonce pas au contrôle pour autant, cette vulnérabilité ne dispensant pas de la nécessité de vérifier son identité.", "points": [{"position": 1, "label": "Solliciter un appui complémentaire si l''adaptation initiale ne suffit pas", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Appui complémentaire sollicité.", "groups": [{"position": 1, "keywords": ["appui sollicite", "adaptation insuffisante", "complementarite recherchee"]}]}, {"position": 2, "label": "Rechercher un proche ou un tiers connu facilitant la communication", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recherche d''un tiers facilitateur.", "groups": [{"position": 1, "keywords": ["proche recherche", "tiers connu", "communication facilitee"]}]}, {"position": 3, "label": "Solliciter les services compétents pour un avis adapté", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recours aux services compétents.", "groups": [{"position": 1, "keywords": ["services sollicites", "avis adapte", "competence recherchee"]}]}, {"position": 4, "label": "Ne pas renoncer au contrôle malgré cette vulnérabilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Contrôle maintenu malgré la difficulté.", "groups": [{"position": 1, "keywords": ["controle maintenu", "renoncement evite", "necessite rappelee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous ce contrôle et en rendez-vous compte ?", "hint": "Cette vulnérabilité constatée mérite d''être mentionnée précisément dans votre compte rendu, au-delà du seul résultat du contrôle.", "perfect": "Je conclus ce contrôle dès que l''identité a pu être établie, avec ou sans l''appui complémentaire sollicité, sans prolonger inutilement cette situation. Je rends compte précisément de la vulnérabilité constatée dans mon compte rendu, cette information pouvant s''avérer utile pour cette personne à l''avenir. Je signale, le cas échéant, cette situation aux services compétents si un accompagnement complémentaire me paraît nécessaire. Je reste bienveillante jusqu''au terme de cet échange, cette personne n''ayant manifesté aucune volonté d''obstruction tout au long du contrôle.", "points": [{"position": 1, "label": "Conclure le contrôle dès que l''identité est établie sans prolonger inutilement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clôture proportionnée.", "groups": [{"position": 1, "keywords": ["controle conclu", "identite etablie", "prolongation evitee"]}]}, {"position": 2, "label": "Rendre compte précisément de la vulnérabilité constatée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilité de la vulnérabilité.", "groups": [{"position": 1, "keywords": ["vulnerabilite signalee", "compte rendu precis", "information utile"]}]}, {"position": 3, "label": "Signaler la situation aux services compétents si un accompagnement paraît nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orientation vers un accompagnement.", "groups": [{"position": 1, "keywords": ["signalement effectue", "accompagnement envisage", "services alertes"]}]}, {"position": 4, "label": "Rester bienveillante jusqu''au terme de l''échange", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Bienveillance continue.", "groups": [{"position": 1, "keywords": ["bienveillance maintenue", "echange termine", "obstruction absente"]}]}]}]}'::jsonb);

-- ci-controle-suite-signalement-erronne — Le signalement ne correspond pas, il est contrôlé quand même
SELECT public.fn_cp_import_case('ci-controle-suite-signalement-erronne', '{"slug": "ci-controle-suite-signalement-erronne", "title": "Le signalement ne correspond pas, il est contrôlé quand même", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Vous engagez un contrôle d''identité sur une personne correspondant, selon les informations initiales transmises par radio, au signalement d''un individu recherché dans le cadre d''une affaire en cours. Dès les premiers échanges et la vérification de ses documents, il apparaît clairement que cette personne ne correspond pas à ce signalement : son âge, sa description physique précise et les éléments qu''elle présente ne concordent pas avec les caractéristiques recherchées. Le contrôle, engagé de bonne foi sur la base d''une ressemblance générale, perd donc son fondement initial en cours d''exécution. La personne contrôlée, jusque-là coopérative, commence à manifester une certaine incompréhension face à la poursuite de l''échange après cette clarification.", "questions": [{"position": 1, "max_points": 5, "label": "Que faites-vous dès lors que vous constatez que le signalement ne correspond pas ?", "hint": "Un contrôle qui perd son fondement en cours d''exécution ne doit pas se poursuivre comme si de rien n''était.", "perfect": "Je mets fin au contrôle dès que je constate que le signalement ne correspond pas, cette clarification devant immédiatement modifier la conduite de l''échange. Je ne cherche pas à prolonger artificiellement ce contrôle par acquis de conscience, cette pratique n''étant pas justifiée une fois le doute levé. J''explique clairement à la personne la méprise initiale, cette transparence restant la moindre des choses après l''avoir mobilisée sans fondement. Je reste courtoise dans cette clôture, cette méprise n''étant en rien imputable à un comportement de sa part.", "points": [{"position": 1, "label": "Mettre fin au contrôle dès la constatation de la non-correspondance", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["controle arrete", "non correspondance constatee", "fin immediate"]}]}, {"position": 2, "label": "Ne pas prolonger artificiellement le contrôle par acquis de conscience", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Absence de prolongation injustifiée.", "groups": [{"position": 1, "keywords": ["prolongation evitee", "acquis de conscience ecarte", "doute leve"]}]}, {"position": 3, "label": "Expliquer clairement la méprise initiale à la personne", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sur la méprise.", "groups": [{"position": 1, "keywords": ["meprise expliquee", "transparence assuree", "clarification donnee"]}]}, {"position": 4, "label": "Rester courtoise dans la clôture, la méprise n''étant pas imputable à la personne", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Courtoisie dans la clôture.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "meprise non imputable", "cloture respectueuse"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment répondez-vous à l''incompréhension qu''exprime la personne contrôlée ?", "hint": "Cette personne a le droit de comprendre pourquoi elle a été mobilisée pour rien.", "perfect": "Je réponds à son incompréhension avec sincérité, cette personne étant légitimement en droit de comprendre les raisons de cette interpellation infondée. J''assume clairement la méprise sans en minimiser la réalité ni chercher d''excuse dilatoire. Je reste factuelle sur les éléments qui avaient initialement motivé ce contrôle, sans divulguer de détails inutiles sur l''affaire en cours. Je m''assure, avant de la laisser repartir, qu''elle ne conserve pas un sentiment d''injustice non traité par mes explications.", "points": [{"position": 1, "label": "Répondre avec sincérité à l''incompréhension exprimée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Sincérité de la réponse.", "groups": [{"position": 1, "keywords": ["sincerite assuree", "incomprehension traitee", "reponse honnete"]}]}, {"position": 2, "label": "Assumer clairement la méprise sans excuse dilatoire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Responsabilité assumée.", "groups": [{"position": 1, "keywords": ["meprise assumee", "excuse dilatoire evitee", "responsabilite reconnue"]}]}, {"position": 3, "label": "Rester factuelle sans divulguer de détails inutiles sur l''affaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Confidentialité de l''affaire en cours.", "groups": [{"position": 1, "keywords": ["details non divulgues", "confidentialite respectee", "factuel maintenu"]}]}, {"position": 4, "label": "S''assurer qu''elle ne reparte pas avec un sentiment d''injustice non traité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sentiment d''injustice traité.", "groups": [{"position": 1, "keywords": ["injustice traitee", "sentiment apaise", "depart serein"]}]}]}, {"position": 3, "max_points": 5, "label": "Que faites-vous du signalement initial qui s''est révélé inadapté à cette description ?", "hint": "Cette expérience peut être utile pour éviter que d''autres contrôles infondés ne se reproduisent sur la même base.", "perfect": "Je rends compte de cette vérification à ma hiérarchie, cette information pouvant utilement affiner la diffusion du signalement initial si celui-ci s''avère imprécis. Je précise dans mon compte rendu les éléments qui ont permis d''exclure cette personne, cette rigueur pouvant éviter des contrôles similaires infondés. Je ne considère pas ce contrôle comme un échec personnel, cette vérification ayant précisément rempli son rôle en écartant une fausse piste. Je reste disponible pour tout complément d''information que mes collègues pourraient solliciter sur cette vérification.", "points": [{"position": 1, "label": "Rendre compte de cette vérification pour affiner la diffusion du signalement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Amélioration du signalement diffusé.", "groups": [{"position": 1, "keywords": ["compte rendu effectue", "signalement affine", "hierarchie informee"]}]}, {"position": 2, "label": "Préciser les éléments ayant permis d''exclure cette personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision des éléments d''exclusion.", "groups": [{"position": 1, "keywords": ["elements precises", "exclusion motivee", "rigueur assuree"]}]}, {"position": 3, "label": "Ne pas considérer ce contrôle comme un échec personnel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recul professionnel sur la vérification.", "groups": [{"position": 1, "keywords": ["echec non ressenti", "role rempli", "fausse piste ecartee"]}]}, {"position": 4, "label": "Rester disponible pour tout complément d''information sollicité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité continue.", "groups": [{"position": 1, "keywords": ["disponibilite assuree", "complement possible", "collegues informes"]}]}]}]}'::jsonb);

