-- ci-controle-mineur-tres-jeune — Il a onze ans et se trouve seul à cette heure
SELECT public.fn_cp_import_case('ci-controle-mineur-tres-jeune', '{"slug": "ci-controle-mineur-tres-jeune", "title": "Il a onze ans et se trouve seul à cette heure", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 20 heures. Vous croisez dans un quartier un garçon qui, selon son propre récit, a onze ans et se trouve seul, sans accompagnement d''un adulte, à une heure et dans un lieu qui interrogent sur les raisons de sa présence isolée. Il ne présente aucun document d''identité, ce qui est habituel à son âge, et donne verbalement son nom et son adresse avec une certaine hésitation. Il affirme rentrer d''une activité sans plus de précision, sans manifester d''inquiétude particulière pour lui-même. L''enjeu de ce contrôle dépasse largement la seule vérification identitaire : sa présence isolée à cette heure interroge davantage sur sa protection que sur une éventuelle infraction qu''il aurait commise.", "questions": [{"position": 1, "max_points": 5, "label": "Comment orientez-vous d''emblée votre approche face à cette situation ?", "hint": "Face à un enfant de cet âge seul à cette heure, la question de la protection prime sur l''aspect identitaire du contrôle.", "perfect": "J''oriente d''emblée mon approche vers la protection de cet enfant plutôt que vers un contrôle d''identité classique, cet aspect protecteur devant primer compte tenu de son âge et de l''heure. J''adopte un ton bienveillant et rassurant, adapté à son jeune âge, pour ne pas l''effrayer davantage. Je cherche à comprendre les circonstances de sa présence isolée avant toute autre considération, cette compréhension conditionnant la suite à donner. Je ne traite pas cette situation comme un contrôle ordinaire, la vulnérabilité liée à son âge appelant une vigilance renforcée.", "points": [{"position": 1, "label": "Orienter l''approche vers la protection plutôt qu''un contrôle classique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["protection prioritaire", "controle classique ecarte", "age pris en compte"]}]}, {"position": 2, "label": "Adopter un ton bienveillant et rassurant adapté à son âge", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Adaptation du ton à l''enfant.", "groups": [{"position": 1, "keywords": ["ton bienveillant", "rassurant adapte", "jeune age considere"]}]}, {"position": 3, "label": "Chercher à comprendre les circonstances de sa présence isolée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compréhension du contexte.", "groups": [{"position": 1, "keywords": ["circonstances comprises", "presence isolee", "contexte explore"]}]}, {"position": 4, "label": "Ne pas traiter la situation comme un contrôle ordinaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance renforcée.", "groups": [{"position": 1, "keywords": ["controle non ordinaire", "vigilance renforcee", "situation particuliere"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment vérifiez-vous les éléments qu''il vous donne verbalement, dont son adresse ?", "hint": "L''objectif immédiat est de le mettre en sécurité et de contacter ses parents, plus que de vérifier son identité au sens strict.", "perfect": "Je cherche à vérifier les éléments qu''il me donne, principalement dans le but de contacter rapidement ses parents ou responsables légaux plutôt que dans un objectif de contrôle identitaire classique. Je reste patiente face à son hésitation, celle-ci pouvant traduire une gêne ou une inquiétude plus qu''une volonté de dissimulation. Je sollicite, si nécessaire, une vérification via mes moyens habituels pour confirmer l''adresse déclarée. Je ne le brusque à aucun moment dans ces vérifications, cette prudence restant essentielle face à un enfant de cet âge.", "points": [{"position": 1, "label": "Vérifier les éléments dans le but de contacter les parents rapidement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Objectif de contact parental.", "groups": [{"position": 1, "keywords": ["contact parents", "verification orientee", "objectif protecteur"]}]}, {"position": 2, "label": "Rester patiente face à son hésitation sans y voir une dissimulation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Patience face à l''hésitation.", "groups": [{"position": 1, "keywords": ["patience assuree", "hesitation comprise", "dissimulation non presumee"]}]}, {"position": 3, "label": "Solliciter une vérification via les moyens habituels pour l''adresse", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérification pratique de l''adresse.", "groups": [{"position": 1, "keywords": ["adresse verifiee", "moyens habituels", "confirmation recherchee"]}]}, {"position": 4, "label": "Ne pas brusquer l''enfant dans ces vérifications", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Douceur maintenue.", "groups": [{"position": 1, "keywords": ["enfant non brusque", "douceur maintenue", "prudence assuree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite pour cet enfant une fois les vérifications engagées ?", "hint": "Le laisser repartir seul, sans certitude sur sa sécurité, ne serait pas une réponse adaptée à ce que vous venez de constater.", "perfect": "Je ne le laisse pas repartir seul tant que je n''ai pas la certitude qu''il rejoindra un adulte responsable en sécurité, cette précaution restant proportionnée à la vulnérabilité constatée. Je contacte ses parents ou responsables légaux dès que possible pour organiser sa prise en charge. Je reste avec lui ou le fais accompagner jusqu''à ce que cette prise en charge soit effective, sans le laisser dans l''incertitude. Je rends compte précisément des circonstances de cette découverte, cette information pouvant s''avérer utile en cas de situation récurrente.", "points": [{"position": 1, "label": "Ne pas le laisser repartir seul sans certitude sur sa sécurité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Précaution proportionnée.", "groups": [{"position": 1, "keywords": ["depart seul evite", "securite garantie", "precaution assuree"]}]}, {"position": 2, "label": "Contacter les parents ou responsables légaux dès que possible", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contact parental effectué.", "groups": [{"position": 1, "keywords": ["parents contactes", "responsables legaux", "prise en charge organisee"]}]}, {"position": 3, "label": "Rester avec lui ou le faire accompagner jusqu''à la prise en charge", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Accompagnement continu.", "groups": [{"position": 1, "keywords": ["accompagnement assure", "prise en charge effective", "enfant non laisse"]}]}, {"position": 4, "label": "Rendre compte précisément des circonstances de cette découverte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité utile en cas de récurrence.", "groups": [{"position": 1, "keywords": ["circonstances documentees", "compte rendu precis", "recurrence anticipee"]}]}]}]}'::jsonb);

-- ci-palpation-securite-contestee — Elle refuse d'être palpée par un agent masculin
SELECT public.fn_cp_import_case('ci-palpation-securite-contestee', '{"slug": "ci-palpation-securite-contestee", "title": "Elle refuse d''être palpée par un agent masculin", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 22 heures. Dans le cadre d''un contrôle d''identité sur la voie publique justifiant une palpation de sécurité, la femme contrôlée demande explicitement à ne pas être palpée par un agent masculin, invoquant une préférence légitime liée à sa pudeur. Vous êtes en patrouille avec un collègue masculin, aucune collègue femme n''étant présente sur ce secteur à cette heure tardive. La demande de cette femme reste posée et respectueuse, sans opposition de principe au contrôle lui-même. Vous devez concilier cette demande légitime avec la contrainte concrète d''effectif que représente l''absence d''une collègue disponible immédiatement sur place.", "questions": [{"position": 1, "max_points": 5, "label": "Comment répondez-vous à cette demande dans l''immédiat ?", "hint": "Cette demande mérite d''être respectée autant que possible, même si elle impose de s''organiser autrement.", "perfect": "Je respecte cette demande autant que possible, celle-ci restant légitime et ne constituant en rien une opposition au contrôle lui-même. J''explique que je vais chercher une solution adaptée compte tenu de l''absence de collègue féminine immédiatement disponible sur place. Je ne minimise pas cette demande ni ne la traite comme un caprice, cette question de dignité méritant une réponse sérieuse. J''informe cette femme des options possibles pour organiser autrement cette palpation dans un délai raisonnable.", "points": [{"position": 1, "label": "Respecter la demande, celle-ci restant légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["demande respectee", "legitimite reconnue", "dignite consideree"]}]}, {"position": 2, "label": "Expliquer la recherche d''une solution adaptée face à la contrainte d''effectif", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explication de la contrainte.", "groups": [{"position": 1, "keywords": ["solution recherchee", "contrainte expliquee", "effectif considere"]}]}, {"position": 3, "label": "Ne pas minimiser ni traiter la demande comme un caprice", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sérieux de la demande.", "groups": [{"position": 1, "keywords": ["demande prise au serieux", "caprice ecarte", "minimisation evitee"]}]}, {"position": 4, "label": "Informer des options possibles dans un délai raisonnable", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information sur les options.", "groups": [{"position": 1, "keywords": ["options informees", "delai raisonnable", "organisation annoncee"]}]}]}, {"position": 2, "max_points": 5, "label": "Concrètement, comment organisez-vous cette palpation compte tenu de l''effectif disponible ?", "hint": "Plusieurs solutions existent avant d''envisager d''imposer une palpation par un agent masculin contre son gré.", "perfect": "J''envisage plusieurs solutions avant d''imposer une palpation par un agent masculin contre son gré, cette contrainte restant un dernier recours. Je sollicite, si le motif de sécurité le permet d''attendre, l''arrivée d''une collègue féminine dans un délai raisonnable. J''évalue également, avec mon collègue, s''il existe un motif de sécurité impérieux justifiant une exception à ce délai. Je reste transparente avec cette femme sur la solution finalement retenue et les raisons qui l''ont guidée.", "points": [{"position": 1, "label": "Envisager plusieurs solutions avant d''imposer une palpation contre son gré", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Recherche de solutions alternatives.", "groups": [{"position": 1, "keywords": ["solutions envisagees", "dernier recours", "gre respecte"]}]}, {"position": 2, "label": "Solliciter l''arrivée d''une collègue féminine si le délai le permet", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recherche d''une collègue.", "groups": [{"position": 1, "keywords": ["collegue sollicitee", "delai raisonnable", "arrivee organisee"]}]}, {"position": 3, "label": "Évaluer avec son collègue un éventuel motif de sécurité impérieux", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Évaluation collégiale de l''urgence.", "groups": [{"position": 1, "keywords": ["motif impérieux evalue", "securite consideree", "evaluation collegiale"]}]}, {"position": 4, "label": "Rester transparente sur la solution retenue et ses raisons", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence sur la décision.", "groups": [{"position": 1, "keywords": ["transparence assuree", "solution expliquee", "raisons partagees"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette situation dans votre rapport ?", "hint": "Cette contrainte récurrente d''effectif mérite d''être signalée au-delà du seul cas individuel.", "perfect": "Je mentionne précisément dans mon compte rendu la demande formulée et la solution retenue pour y répondre, cette traçabilité restant nécessaire. Je signale à ma hiérarchie la difficulté rencontrée en l''absence de collègue féminine disponible, cette information pouvant utilement alimenter une réflexion sur l''organisation des effectifs. Je ne présente pas cette situation comme un incident mais comme une contrainte organisationnelle légitime à anticiper. Je reste factuelle sur le déroulement effectif de cette palpation, quelle que soit la solution finalement retenue.", "points": [{"position": 1, "label": "Mentionner précisément la demande et la solution retenue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilité de la demande et de la solution.", "groups": [{"position": 1, "keywords": ["demande mentionnee", "solution tracee", "compte rendu precis"]}]}, {"position": 2, "label": "Signaler à la hiérarchie la difficulté d''effectif rencontrée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Signalement organisationnel.", "groups": [{"position": 1, "keywords": ["hierarchie informee", "difficulte signalee", "effectif souleve"]}]}, {"position": 3, "label": "Présenter la situation comme une contrainte organisationnelle à anticiper", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Cadrage constructif.", "groups": [{"position": 1, "keywords": ["contrainte organisationnelle", "anticipation suggeree", "incident non presente"]}]}, {"position": 4, "label": "Rester factuelle sur le déroulement effectif de la palpation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Exactitude du compte rendu.", "groups": [{"position": 1, "keywords": ["deroulement factuel", "palpation decrite", "exactitude assuree"]}]}]}]}'::jsonb);

-- ci-controle-professionnel-en-exercice — Un médecin en visite refuse d'interrompre sa tournée
SELECT public.fn_cp_import_case('ci-controle-professionnel-en-exercice', '{"slug": "ci-controle-professionnel-en-exercice", "title": "Un médecin en visite refuse d''interrompre sa tournée", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 11 heures. Vous procédez à un contrôle d''identité en voie publique sur un homme se présentant comme médecin, en pleine tournée de visites à domicile, sacoche professionnelle à la main. Il ne conteste pas la légitimité du contrôle en soi mais insiste pour le faire pendant qu''il marche, expliquant avoir un patient qui l''attend dans un état qu''il qualifie de préoccupant. Il présente sa carte professionnelle ainsi qu''une pièce d''identité, mais refuse de s''arrêter complètement, continuant à avancer à petits pas tout en cherchant ses documents. Cette urgence invoquée, si elle est réelle, mérite considération, sans pour autant que le contrôle ne puisse être mené dans des conditions rigoureuses.", "questions": [{"position": 1, "max_points": 5, "label": "Comment conciliez-vous l''urgence invoquée par ce médecin et la nécessité de mener le contrôle correctement ?", "hint": "Un contrôle mené dans de mauvaises conditions matérielles peut manquer de rigueur, même face à une urgence réelle.", "perfect": "Je demande fermement mais courtoisement qu''il s''arrête complètement le temps strictement nécessaire à ce contrôle, cette rigueur restant nécessaire même face à une urgence invoquée. Je reste attentive au fait que cette urgence, si elle s''avère réelle, mérite d''être prise au sérieux sans pour autant renoncer à la qualité de la vérification. J''explique que ce contrôle sera mené le plus rapidement possible compte tenu de cette contrainte qu''il évoque. Je ne cède pas à la précipitation qu''il tente d''imposer par son insistance à continuer de marcher.", "points": [{"position": 1, "label": "Demander fermement que le contrôle se fasse à l''arrêt", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["arret demande", "controle rigoureux", "fermete appliquee"]}]}, {"position": 2, "label": "Rester attentive à l''urgence invoquée sans renoncer à la rigueur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Équilibre entre urgence et rigueur.", "groups": [{"position": 1, "keywords": ["urgence consideree", "rigueur maintenue", "equilibre assure"]}]}, {"position": 3, "label": "Expliquer que le contrôle sera mené le plus rapidement possible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rapidité expliquée.", "groups": [{"position": 1, "keywords": ["rapidite expliquee", "delai reduit", "contrainte reconnue"]}]}, {"position": 4, "label": "Ne pas céder à la précipitation qu''il tente d''imposer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Résistance à la précipitation.", "groups": [{"position": 1, "keywords": ["precipitation evitee", "insistance geree", "controle maitrise"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment vérifiez-vous les documents professionnels qu''il vous présente ?", "hint": "Une carte professionnelle mérite le même sérieux de vérification qu''une pièce d''identité classique.", "perfect": "Je vérifie ces documents avec le même sérieux qu''un contrôle habituel, la qualité de médecin qu''il invoque ne dispensant en rien d''une vérification rigoureuse. Je consulte sa pièce d''identité en priorité, cette dernière restant l''élément central du contrôle. J''examine sa carte professionnelle avec attention, sans pour autant présumer d''emblée de son authenticité du seul fait de sa présentation assurée. Je reste factuelle et méthodique, sans me laisser influencer par le statut social qu''il affiche.", "points": [{"position": 1, "label": "Vérifier les documents avec le même sérieux qu''un contrôle habituel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur maintenue malgré le statut.", "groups": [{"position": 1, "keywords": ["verification rigoureuse", "meme serieux", "controle habituel"]}]}, {"position": 2, "label": "Consulter la pièce d''identité en priorité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Priorité à l''identité.", "groups": [{"position": 1, "keywords": ["identite consultee", "priorite donnee", "document central"]}]}, {"position": 3, "label": "Examiner la carte professionnelle sans présumer de son authenticité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Absence de présomption d''authenticité.", "groups": [{"position": 1, "keywords": ["carte examinee", "authenticite non presumee", "attention maintenue"]}]}, {"position": 4, "label": "Ne pas se laisser influencer par le statut social affiché", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Neutralité face au statut.", "groups": [{"position": 1, "keywords": ["statut sans influence", "neutralite assuree", "objectivite maintenue"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment clôturez-vous ce contrôle compte tenu de l''urgence qu''il a invoquée ?", "hint": "Une fois les vérifications faites, rien ne justifie de prolonger inutilement ce contrôle.", "perfect": "Je clôture ce contrôle dès que les vérifications nécessaires sont achevées, sans prolonger inutilement compte tenu de l''urgence qu''il a invoquée. Je le remercie pour sa coopération malgré la contrainte que ce contrôle a pu représenter pour lui. Je reste consciente que cette urgence, que je n''ai pas à vérifier moi-même dans son détail médical, mérite d''être respectée dès lors que le contrôle est terminé. Je documente ce contrôle normalement, sans traitement particulier lié à sa profession.", "points": [{"position": 1, "label": "Clôturer sans prolonger inutilement compte tenu de l''urgence invoquée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Clôture proportionnée.", "groups": [{"position": 1, "keywords": ["controle cloture", "prolongation evitee", "urgence respectee"]}]}, {"position": 2, "label": "Remercier pour la coopération malgré la contrainte représentée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie de clôture.", "groups": [{"position": 1, "keywords": ["cooperation remerciee", "contrainte reconnue", "courtoisie finale"]}]}, {"position": 3, "label": "Respecter l''urgence sans en vérifier le détail médical", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Respect de l''urgence sans intrusion.", "groups": [{"position": 1, "keywords": ["urgence respectee", "detail medical non verifie", "confiance accordee"]}]}, {"position": 4, "label": "Documenter le contrôle normalement sans traitement particulier lié à la profession", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Égalité de traitement.", "groups": [{"position": 1, "keywords": ["documentation normale", "traitement egal", "profession sans privilege"]}]}]}]}'::jsonb);

-- ci-controle-personne-connue-des-services — C'est la quatrième fois que vous le contrôlez ce mois-ci
SELECT public.fn_cp_import_case('ci-controle-personne-connue-des-services', '{"slug": "ci-controle-personne-connue-des-services", "title": "C''est la quatrième fois que vous le contrôlez ce mois-ci", "theme_slug": "controle-identite", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Vous croisez, dans un quartier que vous patrouillez régulièrement, un jeune homme que vous reconnaissez pour l''avoir déjà contrôlé à trois reprises au cours du même mois, toujours dans des circonstances différentes mais sans qu''aucun de ces contrôles précédents n''ait révélé d''élément particulier. Vous engagez, dans le cadre d''une réquisition en vigueur sur ce secteur, un quatrième contrôle. Il vous fait remarquer, sans agressivité mais avec une lassitude perceptible, qu''il commence à trouver cette répétition difficile à comprendre, se demandant s''il n''est pas visé personnellement. Vous devez décider si ce nouveau contrôle est justifié indépendamment des précédents, et comment répondre à cette remarque légitime.", "questions": [{"position": 1, "max_points": 5, "label": "Ce nouveau contrôle est-il justifié, et sur quelle base l''appréciez-vous ?", "hint": "Chaque contrôle doit reposer sur son propre fondement, indépendamment du nombre de fois où la même personne a déjà été contrôlée.", "perfect": "J''apprécie ce contrôle indépendamment des précédents, chaque contrôle devant reposer sur son propre fondement et non sur la simple habitude de croiser cette personne. Je vérifie que la réquisition en vigueur sur ce secteur s''applique bien à ce contrôle précis, comme elle s''appliquerait à toute autre personne présente au même endroit. Je m''interroge honnêtement sur la part que pourrait jouer la reconnaissance de son visage dans ma décision d''engager ce contrôle, cette vigilance sur moi-même restant nécessaire. Je n''engage ce contrôle que si je peux le justifier de la même manière que s''il s''agissait d''une personne inconnue.", "points": [{"position": 1, "label": "Justifier chaque contrôle indépendamment des précédents", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["justification independante", "controle propre fondement", "precedents ecartes"]}]}, {"position": 2, "label": "Vérifier que la réquisition s''applique comme pour toute autre personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Application égale de la réquisition.", "groups": [{"position": 1, "keywords": ["requisition verifiee", "application egale", "meme regle"]}]}, {"position": 3, "label": "S''interroger honnêtement sur le rôle de la reconnaissance du visage", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Auto-vigilance sur le biais.", "groups": [{"position": 1, "keywords": ["reconnaissance interrogee", "biais examine", "vigilance sur soi"]}]}, {"position": 4, "label": "N''engager le contrôle que s''il serait justifié pour une personne inconnue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Test d''impartialité appliqué.", "groups": [{"position": 1, "keywords": ["personne inconnue", "test appliqué", "impartialite verifiee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment répondez-vous à sa remarque sur cette répétition et son sentiment d''être visé ?", "hint": "Cette remarque, formulée sans agressivité, mérite une réponse respectueuse plutôt qu''une justification défensive.", "perfect": "Je réponds à sa remarque avec respect, cette lassitude qu''il exprime étant compréhensible et méritant une réponse plutôt qu''un silence gêné. J''explique que ce contrôle repose sur le cadre en vigueur sur ce secteur, applicable à toute personne présente, sans lien avec les contrôles précédents. Je reconnais que cette répétition peut être difficile à vivre, sans pour autant renier la légitimité de chacun des contrôles pris individuellement. Je reste à l''écoute de ce qu''il exprime, cette écoute contribuant à préserver la relation de confiance malgré la répétition.", "points": [{"position": 1, "label": "Répondre avec respect à cette remarque légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Respect de la remarque exprimée.", "groups": [{"position": 1, "keywords": ["reponse respectueuse", "remarque entendue", "legitimite reconnue"]}]}, {"position": 2, "label": "Expliquer que le contrôle repose sur le cadre applicable à tous", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explication du cadre général.", "groups": [{"position": 1, "keywords": ["cadre explique", "application generale", "lien avec precedents ecarte"]}]}, {"position": 3, "label": "Reconnaître la difficulté de cette répétition sans renier la légitimité des contrôles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance de la difficulté vécue.", "groups": [{"position": 1, "keywords": ["difficulte reconnue", "legitimite maintenue", "repetition admise"]}]}, {"position": 4, "label": "Rester à l''écoute pour préserver la relation de confiance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Confiance préservée.", "groups": [{"position": 1, "keywords": ["ecoute maintenue", "confiance preservee", "relation soignee"]}]}]}, {"position": 3, "max_points": 5, "label": "Faites-vous quelque chose de particulier après ce quatrième contrôle, au-delà de son issue immédiate ?", "hint": "Une répétition de contrôles sur la même personne peut mériter un signalement, indépendamment du résultat de chacun d''eux.", "perfect": "Je signale à ma hiérarchie cette répétition de contrôles sur la même personne au cours d''une même période, cette information pouvant utilement éclairer une appréciation d''ensemble. Je documente précisément le fondement propre à ce quatrième contrôle, distinct des précédents. Je n''hésite pas à faire remonter mon propre questionnement sur la part de reconnaissance individuelle dans ce contrôle, cette transparence relevant d''une réflexion professionnelle saine. Je reste attentive, à l''avenir, à ne pas engager de contrôle sur cette personne sur la seule base de sa reconnaissance.", "points": [{"position": 1, "label": "Signaler à la hiérarchie cette répétition de contrôles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Signalement de la répétition.", "groups": [{"position": 1, "keywords": ["repetition signalee", "hierarchie informee", "controles multiples"]}]}, {"position": 2, "label": "Documenter précisément le fondement propre à ce quatrième contrôle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Documentation distincte des précédents.", "groups": [{"position": 1, "keywords": ["fondement documente", "quatrieme controle", "distinction assuree"]}]}, {"position": 3, "label": "Faire remonter son propre questionnement sur le biais possible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sur le questionnement personnel.", "groups": [{"position": 1, "keywords": ["questionnement partage", "reflexion professionnelle", "transparence assuree"]}]}, {"position": 4, "label": "Rester attentive à l''avenir à ne pas contrôler sur la seule reconnaissance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance future.", "groups": [{"position": 1, "keywords": ["vigilance future", "reconnaissance seule evitee", "attention durable"]}]}]}]}'::jsonb);

-- ci-controle-lors-d-un-evenement-festif — Il est euphorique et tutoie tout le monde, sans agressivité
SELECT public.fn_cp_import_case('ci-controle-lors-d-un-evenement-festif', '{"slug": "ci-controle-lors-d-un-evenement-festif", "title": "Il est euphorique et tutoie tout le monde, sans agressivité", "theme_slug": "controle-identite", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 23 heures. Dans le cadre d''un dispositif de sécurité sur un festival, vous contrôlez l''identité d''un jeune homme visiblement euphorique par l''ambiance de l''événement, sans que rien n''indique une consommation d''alcool ou de produit. Il tutoie spontanément tout le monde autour de lui, y compris vous-même, et plaisante en cherchant ses papiers, sans jamais se montrer irrespectueux ni agressif. Ce registre familier, propre à l''ambiance festive du lieu, tranche avec le cadre habituellement plus formel d''un contrôle d''identité. Vous devez mener ce contrôle normalement, sans vous laisser gagner par cette ambiance ni réagir de façon excessive à ce tutoiement spontané et bon enfant.", "questions": [{"position": 1, "max_points": 5, "label": "Comment réagissez-vous à ce tutoiement spontané et à ce registre familier ?", "hint": "Ce registre n''est ni un manque de respect ni une provocation : le contexte festif l''explique largement.", "perfect": "Je ne réagis pas de façon excessive à ce tutoiement, celui-ci relevant clairement du contexte festif et non d''un manque de respect délibéré. Je maintiens de mon côté un registre professionnel, sans pour autant sanctionner ou reprendre sèchement ce jeune homme pour son ton. Je reste courtoise et légèrement souriante, cette attitude restant adaptée à l''ambiance sans pour autant relâcher le sérieux du contrôle. Je ne me laisse pas non plus entraîner dans ce registre familier, gardant une juste distance professionnelle.", "points": [{"position": 1, "label": "Ne pas réagir de façon excessive à ce tutoiement contextuel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["tutoiement non sanctionne", "contexte festif", "reaction proportionnee"]}]}, {"position": 2, "label": "Maintenir un registre professionnel sans sanctionner le ton employé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Registre professionnel maintenu.", "groups": [{"position": 1, "keywords": ["registre professionnel", "ton non sanctionne", "serieux maintenu"]}]}, {"position": 3, "label": "Rester courtoise et légèrement souriante en adaptant l''attitude", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Adaptation courtoise au contexte.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "attitude adaptee", "sourire mesure"]}]}, {"position": 4, "label": "Ne pas se laisser entraîner dans ce registre familier", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Distance professionnelle gardée.", "groups": [{"position": 1, "keywords": ["distance professionnelle", "registre non adopte", "juste mesure"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment menez-vous concrètement ce contrôle dans ce cadre festif et bruyant ?", "hint": "Le bruit et l''affluence de ce type d''événement peuvent compliquer matériellement un contrôle par ailleurs sans difficulté particulière.", "perfect": "Je mène ce contrôle avec la même rigueur qu''en toute autre circonstance, l''ambiance festive ne devant pas relâcher mon attention sur les vérifications habituelles. Je m''adapte au bruit et à l''affluence propres à ce type d''événement, en me plaçant si besoin dans un endroit un peu plus calme pour faciliter l''échange. Je reste efficace pour ne pas mobiliser cette personne plus longtemps que nécessaire, ce type d''événement générant naturellement de nombreuses sollicitations. Je garde un œil sur l''environnement pendant ce contrôle, cette vigilance restant utile dans un contexte de forte affluence.", "points": [{"position": 1, "label": "Mener le contrôle avec la même rigueur qu''en toute circonstance", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur maintenue malgré l''ambiance.", "groups": [{"position": 1, "keywords": ["rigueur maintenue", "verifications habituelles", "ambiance sans relachement"]}]}, {"position": 2, "label": "S''adapter au bruit et à l''affluence en se plaçant dans un endroit plus calme", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Adaptation pratique au contexte.", "groups": [{"position": 1, "keywords": ["bruit gere", "endroit calme", "adaptation pratique"]}]}, {"position": 3, "label": "Rester efficace pour ne pas mobiliser la personne plus longtemps que nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Efficacité du contrôle.", "groups": [{"position": 1, "keywords": ["efficacite assuree", "mobilisation limitee", "duree maitrisee"]}]}, {"position": 4, "label": "Garder un œil sur l''environnement pendant le contrôle", "weight": 1.0, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance environnementale.", "groups": [{"position": 1, "keywords": ["environnement surveille", "vigilance maintenue", "affluence consideree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment clôturez-vous ce contrôle dans cette ambiance particulière ?", "hint": "Une clôture courtoise, en phase avec le ton bon enfant de la personne, reste tout à fait appropriée ici.", "perfect": "Je clôture ce contrôle avec la même courtoisie qu''à son début, cette ambiance festive et bon enfant ne nécessitant aucune froideur particulière de ma part. Je lui souhaite, comme il est naturel dans ce contexte, de profiter du reste de l''événement, ce geste restant adapté à la situation. Je documente ce contrôle normalement, sans mention particulière liée à ce registre familier qui ne constitue en rien une anomalie à signaler. Je reste disponible si une autre sollicitation survient dans la suite de ce dispositif de sécurité.", "points": [{"position": 1, "label": "Clôturer avec la même courtoisie qu''au début du contrôle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Courtoisie constante.", "groups": [{"position": 1, "keywords": ["courtoisie constante", "cloture soignee", "ton maintenu"]}]}, {"position": 2, "label": "Adapter le geste de clôture à l''ambiance festive", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Geste adapté au contexte.", "groups": [{"position": 1, "keywords": ["geste adapte", "ambiance respectee", "cloture naturelle"]}]}, {"position": 3, "label": "Documenter normalement sans mention particulière liée au registre familier", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Documentation normale.", "groups": [{"position": 1, "keywords": ["documentation normale", "registre non signale", "anomalie absente"]}]}, {"position": 4, "label": "Rester disponible pour la suite du dispositif de sécurité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité pour la suite du service.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "dispositif poursuivi", "service continu"]}]}]}]}'::jsonb);

