-- ci-controle-vehicule-occupants-multiples — Cinq occupants, versions différentes sur leur destination
SELECT public.fn_cp_import_case('ci-controle-vehicule-occupants-multiples', '{"slug": "ci-controle-vehicule-occupants-multiples", "title": "Cinq occupants, versions différentes sur leur destination", "theme_slug": "controle-identite", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 2 heures du matin. Vous interceptez, dans le cadre d''une réquisition, un véhicule occupant cinq personnes sur une route peu fréquentée à cette heure. En les interrogeant séparément sur leur destination, vous obtenez des réponses divergentes : le conducteur évoque une destination, deux passagers en citent une autre, et les deux derniers restent vagues. Ces incohérences peuvent avoir des explications multiples et anodines, sans qu''aucune ne se dégage clairement à ce stade. L''effectif du véhicule dépasse le vôtre, et l''heure tardive ainsi que l''isolement du lieu appellent une vigilance particulière sur le plan de la sécurité avant même d''explorer ces incohérences plus avant.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sécurisez-vous ce contrôle avant d''explorer les incohérences constatées ?", "hint": "La sécurité de l''interception prime sur l''exploration immédiate des versions divergentes.", "perfect": "Je sécurise en priorité ce contrôle avant toute chose, l''effectif du véhicule et l''isolement du lieu à cette heure appelant une vigilance particulière. Je sollicite un renfort compte tenu de ce déséquilibre numérique et de l''heure tardive, cette précaution restant proportionnée aux circonstances. Je positionne le véhicule de service et mon collègue de manière à garder une vue d''ensemble sur l''ensemble des occupants. Je ne me précipite pas vers l''exploration des incohérences avant d''avoir sécurisé matériellement la situation.", "points": [{"position": 1, "label": "Sécuriser le contrôle avant d''explorer les incohérences", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["securisation prioritaire", "incoherences differees", "vigilance appliquee"]}]}, {"position": 2, "label": "Solliciter un renfort compte tenu du déséquilibre numérique et de l''heure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Renfort proportionné aux circonstances.", "groups": [{"position": 1, "keywords": ["renfort sollicite", "desequilibre numerique", "heure tardive"]}]}, {"position": 3, "label": "Positionner le véhicule et le collègue pour garder une vue d''ensemble", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Positionnement tactique.", "groups": [{"position": 1, "keywords": ["positionnement adapte", "vue d ensemble", "collegue implique"]}]}, {"position": 4, "label": "Ne pas se précipiter vers l''exploration avant sécurisation matérielle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ordre des priorités respecté.", "groups": [{"position": 1, "keywords": ["precipitation evitee", "securisation d abord", "ordre respecte"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment explorez-vous ces divergences sans les surinterpréter ?", "hint": "Des versions divergentes sur une destination peuvent avoir des explications anodines qu''il convient d''envisager sereinement.", "perfect": "J''explore ces divergences avec méthode, sans céder à une interprétation prématurée qui verrait dans chaque incohérence un indice de gravité. Je reformule mes questions de manière neutre, en évitant toute suggestion qui orienterait les réponses. Je reste attentive à la possibilité d''explications anodines, comme une mauvaise coordination entre des occupants qui ne voyageaient pas initialement ensemble. Je documente précisément ce que chacun a déclaré, sans en tirer de conclusion hâtive à ce stade de l''échange.", "points": [{"position": 1, "label": "Explorer avec méthode sans interprétation prématurée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Méthode sans surinterprétation.", "groups": [{"position": 1, "keywords": ["exploration methodique", "interpretation prematuree evitee", "gravite non presumee"]}]}, {"position": 2, "label": "Reformuler les questions de manière neutre sans suggestion orientée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Neutralité des questions.", "groups": [{"position": 1, "keywords": ["questions neutres", "suggestion evitee", "reformulation adaptee"]}]}, {"position": 3, "label": "Envisager la possibilité d''explications anodines", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ouverture aux explications simples.", "groups": [{"position": 1, "keywords": ["explications anodines", "coordination imparfaite", "ouverture maintenue"]}]}, {"position": 4, "label": "Documenter précisément les déclarations sans conclusion hâtive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation rigoureuse.", "groups": [{"position": 1, "keywords": ["declarations documentees", "conclusion differee", "rigueur assuree"]}]}]}, {"position": 3, "max_points": 5, "label": "Quelle suite donnez-vous à ce contrôle une fois ces éléments recueillis ?", "hint": "La décision finale doit reposer sur l''ensemble des éléments objectifs, pas sur la seule impression laissée par les divergences.", "perfect": "Je fonde ma décision finale sur l''ensemble des éléments objectifs recueillis, et non sur la seule impression subjective laissée par ces divergences de destination. Si aucun élément concret ne vient étayer un soupçon caractérisé au-delà de ces incohérences verbales, je laisse le véhicule repartir normalement. Je rends compte précisément de ce contrôle, y compris des divergences constatées, dans mon compte rendu de service. Je reste disponible si un élément ultérieur venait éclairer différemment cette situation observée cette nuit-là.", "points": [{"position": 1, "label": "Fonder la décision sur les éléments objectifs, pas sur la seule impression", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Décision fondée objectivement.", "groups": [{"position": 1, "keywords": ["elements objectifs", "impression ecartee", "decision fondee"]}]}, {"position": 2, "label": "Laisser repartir en l''absence d''élément concret au-delà des incohérences verbales", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Proportionnalité de la suite.", "groups": [{"position": 1, "keywords": ["depart autorise", "soupcon non caracterise", "proportionnalite assuree"]}]}, {"position": 3, "label": "Rendre compte précisément du contrôle et des divergences constatées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilité du contrôle.", "groups": [{"position": 1, "keywords": ["compte rendu precis", "divergences tracees", "controle documente"]}]}, {"position": 4, "label": "Rester disponible pour tout élément ultérieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité continue.", "groups": [{"position": 1, "keywords": ["disponibilite assuree", "element ulterieur", "suivi possible"]}]}]}]}'::jsonb);

-- ci-personne-presente-document-douteux — La photographie semble avoir été remplacée
SELECT public.fn_cp_import_case('ci-personne-presente-document-douteux', '{"slug": "ci-personne-presente-document-douteux", "title": "La photographie semble avoir été remplacée", "theme_slug": "controle-identite", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 15 heures. Lors d''un contrôle d''identité, l''examen du document présenté révèle des éléments qui vous interpellent : le bord de la photographie semble légèrement décollé et une texture différente du reste du support est perceptible au toucher. Ces signes ne constituent pas une certitude absolue de falsification, un document authentique pouvant présenter des défauts d''usure ou de fabrication similaires. La personne contrôlée ne manifeste aucune nervosité particulière et répond de manière cohérente aux questions posées sur les éléments figurant sur ce document. Vous devez mener cette vérification avec rigueur, sans accuser prématurément cette personne d''une falsification qui reste, à ce stade, un simple soupçon.", "questions": [{"position": 1, "max_points": 5, "label": "Comment menez-vous la vérification de ce document sans accuser prématurément la personne ?", "hint": "Un soupçon n''est pas une certitude : la manière de vérifier compte autant que la vérification elle-même.", "perfect": "Je mène cette vérification avec méthode, sans formuler d''accusation avant d''avoir des éléments plus certains que ce simple soupçon initial. J''examine le document avec attention, en comparant les éléments visibles à ce que je connais des caractéristiques habituelles de ce type de pièce. Je pose des questions factuelles sur les informations figurant sur le document, sans en faire une confrontation accusatoire. Je reste courtoise tout au long de cet examen, cette personne n''ayant, à ce stade, commis aucune faute avérée.", "points": [{"position": 1, "label": "Mener la vérification sans accusation prématurée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["accusation evitee", "verification methodique", "soupcon non certitude"]}]}, {"position": 2, "label": "Examiner le document en comparant aux caractéristiques habituelles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Examen comparatif rigoureux.", "groups": [{"position": 1, "keywords": ["examen attentif", "caracteristiques comparees", "document analyse"]}]}, {"position": 3, "label": "Poser des questions factuelles sans confrontation accusatoire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Questions factuelles et respectueuses.", "groups": [{"position": 1, "keywords": ["questions factuelles", "confrontation evitee", "ton respectueux"]}]}, {"position": 4, "label": "Rester courtoise tout au long de l''examen", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Courtoisie maintenue.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "faute non avere", "attitude respectueuse"]}]}]}, {"position": 2, "max_points": 5, "label": "Quels moyens complémentaires mobilisez-vous pour lever ce doute ?", "hint": "Vous n''êtes pas seule habilitée à trancher définitivement sur l''authenticité d''un document : d''autres ressources existent.", "perfect": "Je mobilise les moyens complémentaires disponibles pour lever ce doute plutôt que de trancher seule sur la seule base de mon examen visuel. Je sollicite, si nécessaire, une vérification dans les fichiers accessibles pour confirmer la cohérence des informations figurant sur ce document. Je fais appel, si le doute persiste, aux services spécialisés dans l''''authentification documentaire, cette expertise dépassant mes seules compétences. Je consigne précisément les éléments qui ont motivé mon doute initial, cette traçabilité restant utile quelle que soit l''''issue de cette vérification.", "points": [{"position": 1, "label": "Mobiliser les moyens complémentaires plutôt que trancher seule", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Recours aux moyens complémentaires.", "groups": [{"position": 1, "keywords": ["moyens mobilises", "doute leve", "verification approfondie"]}]}, {"position": 2, "label": "Solliciter une vérification dans les fichiers accessibles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérification fichiers.", "groups": [{"position": 1, "keywords": ["fichiers consultes", "coherence verifiee", "informations confirmees"]}]}, {"position": 3, "label": "Faire appel aux services spécialisés en authentification documentaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recours à l''expertise spécialisée.", "groups": [{"position": 1, "keywords": ["services specialises", "authentification documentaire", "expertise sollicitee"]}]}, {"position": 4, "label": "Consigner précisément les éléments ayant motivé le doute initial", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité du doute.", "groups": [{"position": 1, "keywords": ["elements consignes", "doute trace", "motivation documentee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la suite immédiate de ce contrôle pendant que le doute n''est pas encore levé ?", "hint": "Le temps nécessaire à la vérification impose de gérer la situation avec la personne pendant cette attente.", "perfect": "Je gère cette attente avec transparence, expliquant à la personne que je dois procéder à des vérifications complémentaires avant de conclure ce contrôle. Je reste proportionnée dans les mesures prises pendant cette vérification, sans excès de contrainte injustifié par le seul doute actuel. Je surveille la situation avec attention pendant cette attente, sans pour autant traiter cette personne comme si la falsification était déjà établie. Je conclus rapidement ce contrôle dès que la vérification complémentaire apporte une réponse, dans un sens comme dans l''autre.", "points": [{"position": 1, "label": "Gérer l''attente avec transparence sur les vérifications en cours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Transparence pendant l''attente.", "groups": [{"position": 1, "keywords": ["attente expliquee", "verifications annoncees", "transparence assuree"]}]}, {"position": 2, "label": "Rester proportionnée dans les mesures prises pendant la vérification", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Proportionnalité des mesures.", "groups": [{"position": 1, "keywords": ["mesures proportionnees", "contrainte limitee", "exces evite"]}]}, {"position": 3, "label": "Surveiller sans traiter la personne comme coupable avant vérification", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Présomption d''innocence respectée.", "groups": [{"position": 1, "keywords": ["surveillance mesuree", "culpabilite non presumee", "innocence respectee"]}]}, {"position": 4, "label": "Conclure rapidement dès que la vérification complémentaire répond", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Clôture rapide dès réponse obtenue.", "groups": [{"position": 1, "keywords": ["conclusion rapide", "reponse obtenue", "controle termine"]}]}]}]}'::jsonb);

-- ci-controle-issue-negative-relation-degradee — Tout est en règle, la personne repart visiblement humiliée
SELECT public.fn_cp_import_case('ci-controle-issue-negative-relation-degradee', '{"slug": "ci-controle-issue-negative-relation-degradee", "title": "Tout est en règle, la personne repart visiblement humiliée", "theme_slug": "controle-identite", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 13 heures. Vous venez de terminer un contrôle d''identité en voie publique : tous les documents présentés sont en règle, aucune anomalie n''a été constatée, et rien ne justifie de suite particulière. Pourtant, la personne contrôlée, qui s''est montrée coopérative tout au long de l''échange, semble repartir visiblement affectée, le regard bas et les épaules basses, comme humiliée d''avoir été arrêtée en pleine rue devant des passants alors qu''elle n''avait rien à se reprocher. Ce contrôle, parfaitement régulier sur le plan procédural, laisse néanmoins une trace émotionnelle négative que vous percevez clairement dans son attitude au moment de se séparer.", "questions": [{"position": 1, "max_points": 5, "label": "Comment terminez-vous ce contrôle en tenant compte de ce que vous percevez chez cette personne ?", "hint": "La régularité procédurale du contrôle n''épuise pas la question de la manière dont il se termine humainement.", "perfect": "Je termine ce contrôle en portant attention à ce que je perçois chez cette personne, la régularité procédurale n''épuisant pas la dimension humaine de cette fin d''échange. Je la remercie sincèrement pour sa coopération tout au long du contrôle, ce geste simple pouvant contribuer à adoucir ce moment. Je reste attentive à ne pas partir trop vite, ce départ précipité pouvant renforcer le sentiment d''avoir été traitée comme une simple formalité. Je prends le temps, même bref, de clore cet échange avec un minimum de considération humaine.", "points": [{"position": 1, "label": "Porter attention à ce que l''on perçoit chez la personne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["attention portee", "perception consideree", "dimension humaine"]}]}, {"position": 2, "label": "Remercier sincèrement pour la coopération", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Remerciement sincère.", "groups": [{"position": 1, "keywords": ["remerciement sincere", "cooperation reconnue", "geste simple"]}]}, {"position": 3, "label": "Ne pas partir trop vite pour éviter un sentiment de simple formalité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attention au rythme de clôture.", "groups": [{"position": 1, "keywords": ["depart non precipite", "formalite evitee", "rythme adapte"]}]}, {"position": 4, "label": "Prendre le temps, même bref, d''une considération humaine", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Considération humaine finale.", "groups": [{"position": 1, "keywords": ["consideration humaine", "temps accorde", "echange soigne"]}]}]}, {"position": 2, "max_points": 5, "label": "Expliquez-vous à cette personne les raisons de ce contrôle avant qu''elle ne reparte ?", "hint": "Une explication, même brève, peut aider à ce que ce contrôle ne reste pas vécu comme arbitraire.", "perfect": "J''explique brièvement à cette personne le cadre général qui a motivé ce contrôle, cette explication pouvant contribuer à ce qu''elle ne le vive pas comme arbitraire. Je reste honnête sur les raisons de ce contrôle, sans en dissimuler le motif dès lors que je peux le partager. Je ne me justifie pas de manière excessive non plus, cet équilibre restant nécessaire pour ne pas donner l''impression de m''excuser d''avoir fait mon travail. Je réponds à ses éventuelles questions avec la même attention que pendant le reste de l''échange.", "points": [{"position": 1, "label": "Expliquer brièvement le cadre général du contrôle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Explication du cadre.", "groups": [{"position": 1, "keywords": ["cadre explique", "motif partage", "arbitraire evite"]}]}, {"position": 2, "label": "Rester honnête sur les raisons sans les dissimuler", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Honnêteté sur les raisons.", "groups": [{"position": 1, "keywords": ["honnetete assuree", "raisons partagees", "motif clarifie"]}]}, {"position": 3, "label": "Ne pas se justifier de manière excessive", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Équilibre dans la justification.", "groups": [{"position": 1, "keywords": ["justification mesuree", "exces evite", "equilibre maintenu"]}]}, {"position": 4, "label": "Répondre aux questions avec la même attention que pendant l''échange", "weight": 1.0, "is_required": false, "kind": "bonus", "explanation_md": "Attention constante.", "groups": [{"position": 1, "keywords": ["questions accueillies", "attention constante", "echange respecte"]}]}]}, {"position": 3, "max_points": 5, "label": "Cette expérience vécue par la personne appelle-t-elle une réflexion de votre part sur votre pratique ?", "hint": "Un contrôle régulier sur le plan procédural peut néanmoins interroger sur la manière dont il est vécu par la population.", "perfect": "Je m''autorise une réflexion sur ma pratique, cette expérience négative vécue par une personne pourtant en règle méritant d''être prise au sérieux au-delà de la seule régularité procédurale. Je m''interroge sur les gestes ou postures qui, sans intention malveillante, peuvent renforcer ce sentiment d''humiliation chez une personne contrôlée. Je ne me sens pas fautive pour autant, ce contrôle étant resté parfaitement régulier et nécessaire dans son principe. Je reste consciente que la relation entre la police et la population se construit aussi dans ces moments ordinaires, en apparence sans enjeu.", "points": [{"position": 1, "label": "S''autoriser une réflexion sur sa pratique au-delà de la régularité procédurale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réflexion professionnelle continue.", "groups": [{"position": 1, "keywords": ["reflexion engagee", "pratique interrogee", "experience consideree"]}]}, {"position": 2, "label": "S''interroger sur les gestes pouvant renforcer le sentiment d''humiliation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Auto-examen des gestes.", "groups": [{"position": 1, "keywords": ["gestes interroges", "humiliation consideree", "posture examinee"]}]}, {"position": 3, "label": "Ne pas se sentir fautive, le contrôle restant régulier et nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Équilibre entre remise en question et légitimité.", "groups": [{"position": 1, "keywords": ["controle regulier", "necessite reconnue", "culpabilite ecartee"]}]}, {"position": 4, "label": "Rester consciente de l''enjeu relationnel des moments ordinaires", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Conscience de l''enjeu relationnel.", "groups": [{"position": 1, "keywords": ["relation police population", "moments ordinaires", "enjeu conscient"]}]}]}]}'::jsonb);

COMMIT;
